import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { HealthService } from '../../services/health.service';
import { AuthService } from '../../services/auth.service';
import { HealthData } from '../../models/health-data.model';

@Component({
  selector: 'app-upload',
  templateUrl: './upload.component.html',
  styleUrls: ['./upload.component.scss']
})
export class UploadComponent implements OnInit {
  selectedFile: File | null = null;
  previewUrl: string | null = null;
  isUploading = false;
  errorMessage: string = '';

  // Manual entry properties
  showManualEntry = false;
  manualSteps: number = 0;
  manualCalories: number = 0;
  ocrResult: HealthData | null = null;

  constructor(
    private healthService: HealthService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
  }


  onFileSelected(event: any): void {
    const file = event.target.files[0];
    if (file) {
      // Check file size (2MB limit)
      const maxSize = 2 * 1024 * 1024; // 2MB in bytes

      if (file.size > maxSize) {
        const fileSizeMB = (file.size / (1024 * 1024)).toFixed(2);
        this.errorMessage = `File size (${fileSizeMB}MB) exceeds the 2MB limit. Please choose a smaller image.`;
        this.selectedFile = null;
        this.previewUrl = null;

        // Clear the file input
        event.target.value = '';
        return;
      }

      this.selectedFile = file;
      this.errorMessage = '';

      // Create preview URL
      const reader = new FileReader();
      reader.onload = (e: any) => {
        this.previewUrl = e.target.result;
      };
      reader.readAsDataURL(file);
    }
  }

  onSubmit(): void {
    if (this.selectedFile) {
      // Check if user is authenticated
      if (!this.authService.isAuthenticated()) {
        this.errorMessage = 'No valid authentication token found. Please generate a test token first from the home page.';
        return;
      }

      this.isUploading = true;
      this.errorMessage = '';

      this.healthService.uploadImage(this.selectedFile).subscribe({
        next: (data: HealthData) => {
          this.isUploading = false;
          this.ocrResult = data;

          // Check if OCR failed to extract meaningful data
          if (this.isOcrDataEmpty(data)) {
            this.showManualEntry = true;
            this.manualSteps = data.steps || 0;
            this.manualCalories = data.calories || 0;
          } else {
            // OCR worked, navigate to dashboard
            this.router.navigate(['/dashboard'], { 
              state: { 
                data: data,
                isNewUpload: true 
              } 
            });
          }
        },
        error: (error) => {
          console.error('Upload error:', error);
          this.isUploading = false;

          if (error.status === 409) {
            this.errorMessage = error.error.message || 'This image has already been uploaded';
          } else if (error.status === 401) {
            this.errorMessage = 'Authentication failed. Please check your login status.';
          } else if (error.status === 0) {
            this.errorMessage = 'Cannot connect to server. Please check if the backend is running.';
          } else {
            this.errorMessage = error.error?.message || 'Failed to upload image. Please try again.';
          }
        }
      });
    }
  }

  isOcrDataEmpty(data: HealthData): boolean {
    // Consider OCR failed if both steps and calories are 0 or null
    return (!data.steps || data.steps === 0) && (!data.calories || data.calories === 0);
  }

  onManualSubmit(): void {
    if (this.manualSteps > 0 && this.manualCalories > 0) {
      this.isUploading = true;
      this.errorMessage = '';

      this.healthService.uploadImageWithManualData(this.manualSteps, this.manualCalories).subscribe({
        next: (data: HealthData) => {
          this.isUploading = false;
          this.router.navigate(['/dashboard'], { 
            state: { 
              data: data,
              isNewUpload: true 
            } 
          });
        },
        error: (error) => {
          console.error('Manual upload error:', error);
          this.isUploading = false;

          if (error.status === 400) {
            this.errorMessage = error.error.message || 'No recent upload found. Please upload an image first.';
          } else if (error.status === 401) {
            this.errorMessage = 'Authentication failed. Please check your login status.';
          } else if (error.status === 0) {
            this.errorMessage = 'Cannot connect to server. Please check if the backend is running.';
          } else {
            this.errorMessage = error.error?.message || 'Failed to save manual data. Please try again.';
          }
        }
      });
    } else {
      this.errorMessage = 'Please enter valid steps and calories values.';
    }
  }

  onRetryOcr(): void {
    this.showManualEntry = false;
    this.manualSteps = 0;
    this.manualCalories = 0;
    this.ocrResult = null;
    this.errorMessage = '';
  }

  formatFileSize(bytes: number | null | undefined): string {
    if (!bytes) return '';

    if (bytes < 1024) {
      return bytes + ' B';
    } else if (bytes < 1024 * 1024) {
      return (bytes / 1024).toFixed(1) + ' KB';
    } else {
      return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
    }
  }

  goBack(): void {
    this.router.navigate(['/']);
  }
}
<div class="min-h-screen flex flex-col">
  <app-header></app-header>

  <main class="flex-1 px-4 py-6">
    <!-- Header -->
    <div class="flex items-center mb-6">
      <button 
        (click)="goBack()"
        class="p-2 rounded-xl hover:bg-dark-cyan/20 transition-colors mr-3">
        <svg class="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/>
        </svg>
      </button>
      <h1 class="text-2xl font-bold text-white">Upload Fitness Data</h1>
    </div>

    <!-- Upload Form -->
    <div class="bg-gradient-to-br from-cyan/95 to-dark-cyan/90 backdrop-blur-sm rounded-2xl shadow-xl border border-cyan/30 p-6 text-white">
      <form class="space-y-6">
        <!-- Error Message -->
        <div *ngIf="errorMessage" class="bg-red-500/20 border border-red-400/50 text-red-200 px-4 py-3 rounded-lg backdrop-blur-sm">
          {{ errorMessage }}
        </div>

        <!-- File Upload -->
        <div>
          <label class="block text-sm font-semibold text-white mb-2">
            Fitness App Screenshot
          </label>
          <div class="border-2 border-dashed border-white/30 rounded-xl p-6 text-center hover:border-white/60 hover:bg-white/5 transition-all duration-300">
            <input
              type="file"
              id="imageUpload"
              accept="image/*"
              (change)="onFileSelected($event)"
              class="hidden"
            />
            <label for="imageUpload" class="cursor-pointer">
              <div *ngIf="!previewUrl; else previewTemplate" class="space-y-4">
                <div class="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto">
                  <svg class="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
                  </svg>
                </div>
                <div>
                  <p class="text-lg font-medium text-white">Upload your fitness screenshot</p>
                  <p class="text-sm text-white/70">PNG, JPG, or JPEG up to 2MB</p>
                </div>
              </div>

              <ng-template #previewTemplate>
                <div class="space-y-4">
                  <img
                    [src]="previewUrl"
                    alt="Preview"
                    class="max-h-48 mx-auto rounded-xl shadow-lg"
                  />
                  <div class="text-center">
                    <p class="text-sm text-white/70">Tap to change image</p>
                    <p class="text-xs text-white/50">{{ formatFileSize(selectedFile?.size) }}</p>
                  </div>
                </div>
              </ng-template>
            </label>
          </div>
        </div>

        <!-- Submit Button -->
        <button
          type="button"
          (click)="onSubmit()"
          [disabled]="!selectedFile || isUploading"
          class="w-full btn-primary text-lg py-4 flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <div *ngIf="isUploading; else uploadText" class="flex items-center space-x-2">
            <svg class="animate-spin w-5 h-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            <span>Analyzing...</span>
          </div>

          <ng-template #uploadText>
            <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/>
            </svg>
            <span>Analyze Screenshot</span>
          </ng-template>
        </button>
      </form>
    </div>

    <!-- Manual Entry Form (shown when OCR fails) -->
    <div *ngIf="showManualEntry" class="mt-8 bg-gradient-to-r from-orange/90 to-red/80 backdrop-blur-sm rounded-2xl shadow-xl border border-orange/30 p-6 text-white">
      <h3 class="text-lg font-semibold text-white mb-4 flex items-center">
        <svg class="w-5 h-5 text-orange-300 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z"/>
        </svg>
        OCR Couldn't Extract Data
      </h3>

      <p class="text-white/80 mb-6">
        Our OCR couldn't automatically extract the health data from your screenshot. 
        Please manually enter the values below:
      </p>

      <form class="space-y-4">
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
          <!-- Steps Input -->
          <div>
            <label class="block text-sm font-medium text-white/90 mb-2">Steps</label>
            <input
              type="number"
              [(ngModel)]="manualSteps"
              name="manualSteps"
              placeholder="Enter steps count"
              min="0"
              class="w-full px-4 py-3 bg-white/20 border border-white/30 rounded-lg text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-transparent"
            />
          </div>

          <!-- Calories Input -->
          <div>
            <label class="block text-sm font-medium text-white/90 mb-2">Calories</label>
            <input
              type="number"
              [(ngModel)]="manualCalories"
              name="manualCalories"
              placeholder="Enter calories count"
              min="0"
              class="w-full px-4 py-3 bg-white/20 border border-white/30 rounded-lg text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-transparent"
            />
          </div>
        </div>

        <!-- Action Buttons -->
        <div class="flex space-x-4">
          <button
            type="button"
            (click)="onManualSubmit()"
            [disabled]="!manualSteps || !manualCalories || isUploading"
            class="flex-1 bg-orange-600 hover:bg-orange-700 text-white py-3 px-6 rounded-lg font-medium transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
          >
            <div *ngIf="isUploading; else manualSubmitText" class="flex items-center space-x-2">
              <svg class="animate-spin w-5 h-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <span>Uploading...</span>
            </div>

            <ng-template #manualSubmitText>
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"/>
              </svg>
              <span>UData</span>
            </ng-template>
          </button>

          <button
            type="button"
            (click)="onRetryOcr()"
            [disabled]="isUploading"
            class="px-6 py-3 bg-white/20 hover:bg-white/30 text-white rounded-lg font-medium transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Try OCR Again
          </button>
        </div>
      </form>
    </div>

    <!-- Tips -->
    <div class="mt-8 bg-gradient-to-r from-dark-grey/90 to-grey/80 backdrop-blur-sm rounded-2xl shadow-xl border border-grey/30 p-6 text-white">
      <h3 class="text-lg font-semibold text-white mb-4 flex items-center">
        <svg class="w-5 h-5 text-cyan mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
        </svg>
        Tips for Best Results
      </h3>
      <div class="space-y-3">
        <div class="flex items-start space-x-3">
          <div class="w-6 h-6 bg-cyan/30 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-white text-xs font-bold">1</span>
          </div>
          <p class="text-sm text-white/90">Make sure the screenshot is clear and well-lit</p>
        </div>
        <div class="flex items-start space-x-3">
          <div class="w-6 h-6 bg-dark-cyan/40 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-white text-xs font-bold">2</span>
          </div>
          <p class="text-sm text-white/90">Include the main dashboard view with steps and calories visible</p>
        </div>
        <div class="flex items-start space-x-3">
          <div class="w-6 h-6 bg-cyan/30 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-white text-xs font-bold">3</span>
          </div>
          <p class="text-sm text-white/90">Upload regularly to track your progress. Securely integrated with Clienta app.</p>
        </div>
      </div>
    </div>
  </main>
</div>
